// ═══ Stream.iterate — sequence ═══
List<Integer> powers = Stream.iterate(1, n -> n * 2)  // 1, 2, 4, 8, 16...
    .limit(10)                                          // MUST limit — infinite!
    .toList();  // [1, 2, 4, 8, 16, 32, 64, 128, 256, 512]

// Bounded iterate (Java 9):
List<Integer> bounded = Stream.iterate(1, n -> n <= 100, n -> n * 2)
    .toList();  // [1, 2, 4, 8, 16, 32, 64]  — stops when > 100

// ═══ Stream.generate — random/factory ═══
List<String> tokens = Stream.generate(() -> UUID.randomUUID().toString().substring(0, 8))
    .limit(5)
    .toList();  // ["a1b2c3d4", "e5f6g7h8", ...]

// ═══ IntStream.range / rangeClosed ═══
IntStream.range(0, 5).toArray();        // [0, 1, 2, 3, 4]  — exclusive end
IntStream.rangeClosed(1, 5).toArray();  // [1, 2, 3, 4, 5]  — inclusive end

// boxed() — IntStream → Stream<Integer>:
List<Integer> boxed = IntStream.rangeClosed(1, 5)
    .boxed()                              // IntStream → Stream<Integer>
    .toList();                            // List<Integer>

// ═══ WHY LIMIT ON INFINITE ═══
// Stream.generate(Math::random).sorted().findFirst();  // HANGS! sorted buffers ∞ elements!
// Stream.iterate(1, n -> n+1).toList();                // OOM! collects ∞ elements!
// FIX: always .limit(n) before terminal on infinite streams
