package com.bank.builders;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class StreamBuildersTest {

    @Test void iterateInfiniteWithLimit() {
        List<Integer> result = Stream.iterate(1, n -> n * 2).limit(5).toList();
        assertThat(result).containsExactly(1, 2, 4, 8, 16);
    }

    @Test void iterateBoundedJava9() {
        List<Integer> result = Stream.iterate(1, n -> n <= 50, n -> n * 2).toList();
        assertThat(result).containsExactly(1, 2, 4, 8, 16, 32);
    }

    @Test void generateWithLimit() {
        List<Double> randoms = Stream.generate(Math::random).limit(3).toList();
        assertThat(randoms).hasSize(3);
        randoms.forEach(r -> assertThat(r).isBetween(0.0, 1.0));
    }

    @Test void rangeExclusiveEnd() {
        assertThat(IntStream.range(0, 5).toArray()).containsExactly(0, 1, 2, 3, 4);
    }

    @Test void rangeClosedInclusiveEnd() {
        assertThat(IntStream.rangeClosed(1, 5).toArray()).containsExactly(1, 2, 3, 4, 5);
    }

    @Test void boxedConvertsToStreamOfInteger() {
        List<Integer> boxed = IntStream.rangeClosed(1, 3).boxed().toList();
        assertThat(boxed).containsExactly(1, 2, 3);
        assertThat(boxed.get(0)).isInstanceOf(Integer.class);
    }

    @Test void fibonacciWithIterate() {
        List<Long> fib = Stream.iterate(new long[]{0, 1}, f -> new long[]{f[1], f[0] + f[1]})
            .limit(10)
            .map(f -> f[0])
            .toList();
        assertThat(fib).containsExactly(0L, 1L, 1L, 2L, 3L, 5L, 8L, 13L, 21L, 34L);
    }
}
