package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.stream.IntStream;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.assertThat;

class InfiniteStreamTest {

    @Test
    void boundedInfiniteStreams() {
        List<Integer> powers = Stream.iterate(1, x -> x * 2)
            .limit(5)
            .toList();                                   // 1,2,4,8,16
        assertThat(powers).containsExactly(1, 2, 4, 8, 16);

        List<Integer> months = IntStream.rangeClosed(1, 3)
            .boxed()
            .toList();                                   // 1,2,3 as Integer
        assertThat(months).containsExactly(1, 2, 3);
    }
}
